printf "login=%s " "$(shopt -q login_shell && echo yes || echo no)"; printf "BASH_ENV=%s " "${BASH_ENV-unset}"; printf "module=%s " "$(type -t module || echo none)"; printf "LMOD_CMD=%s " "${LMOD_CMD-unset}"; printf "MODULEPATH=%s " "${MODULEPATH:+set}"; printf "LOADED=%s " "${LOADEDMODULES-unset}"; if [ a == a ]; then printf "eqeq=ok "; else printf "eqeq=FAIL "; fi; printf "ml_list=%s" "$( (module -t list 2>&1 || echo module-failed) | tr "\n" ",")"; echo
